import groovy.json.JsonSlurper
import groovy.json.JsonOutput
import org.apache.nifi.processor.io.StreamCallback

def flowFile = session.get()
if (!flowFile) { return }

def jsonSlurper = new JsonSlurper()
def script = [ "lang": "painless" ]
def source = "if (ctx.op != 'create') { def dt = ZonedDateTime.parse(params.new_doc.date_time); def edt = ZonedDateTime.parse(ctx._source.date_time); if (ctx._source.no_value != null) { if ((ctx._source.no_value == false && !params.no_value && !dt.isBefore(edt)) || ctx._source.no_value == true) { ctx._source.clear(); ctx._source.putAll(params.new_doc); } else { ctx.op = 'noop'; } } else { if (!params.no_value && !dt.isBefore(edt)) { ctx._source.clear(); ctx._source.putAll(params.new_doc); } } } else { ctx._source.no_value = params.no_value; }"
def params = [:]
script.put( "source" , source )

try {
    def noValue = flowFile.getAttribute( "no_value" )
    if( noValue != null ) 
        noValue = Boolean.parseBoolean( noValue )
    else
        noValue = false;
    params.put( "no_value" , noValue );

    session.read(flowFile, new InputStreamCallback(){
        void process( InputStream inputStream ){
            def jsonFFContent = jsonSlurper.parse(inputStream)
            jsonFFContent.put( "no_value" , noValue )
            params.put( "new_doc" , jsonFFContent )
        }
    })

    script.put( "params" , params )

    flowFile = session.putAttribute( flowFile , "update_script" , JsonOutput.toJson(script) )
    session.transfer(flowFile, REL_SUCCESS)

} catch (e) {
    log.error("Failed to parse JSON content: " + e.getMessage(), e)
    session.transfer(flowFile, REL_FAILURE)
}

